async def act(page):
    """
    Increase the price of Desiree's black fitness t-shirts size XS by 37%.

    Plan:
    1. Navigate (relative) to the Manage Products grid.
    2. Attempt to filter by product name using accessibility-role based selectors.
    3. Search the product rows (using get_by_role("row")) for a row that contains the texts
       'desiree', 'black', and 'xs' (and optionally 'fitness').
    4. Open the product's edit page by clicking the product link in that row.
    5. On the product edit page, find the price input using get_by_role (or get_by_label as fallback),
       read its numeric value, compute the new price = current * 1.37, fill the new price, and save.

    Notes about knowledge_base functions: none are available, so no special functions are used.
    """
    # 1) Go to Manage Products (use a relative URL)
    await page.goto("/index.php/admin/catalog_product/index/")
    await page.wait_for_load_state("networkidle")

    # 2) Try to filter by product name using accessibility selectors
    filled_filter = False
    try:
        # Prefer an obvious accessible textbox labeled "Name"
        name_box = page.get_by_role("textbox", name="Name")
        if await name_box.count() > 0:
            await name_box.fill("fitness")
            filled_filter = True
    except Exception:
        # ignore and try other accessibility-based fallbacks
        filled_filter = False

    if not filled_filter:
        try:
            # Try to find an input that is associated with a label "Name"
            label_name = page.get_by_role("label", name="Name")
            if await label_name.count() > 0:
                # filter(has=...) expects a Locator; use get_by_role("textbox").filter(has=label_locator)
                textbox_with_label = page.get_by_role("textbox").filter(has=label_name)
                if await textbox_with_label.count() > 0:
                    await textbox_with_label.first.fill("fitness")
                    filled_filter = True
        except Exception:
            filled_filter = False

    if not filled_filter:
        # As a last resort, fill the first textbox on the page (may be the grid filter)
        try:
            first_textbox = page.get_by_role("textbox").first
            if await first_textbox.count() > 0:
                await first_textbox.fill("fitness")
                filled_filter = True
        except Exception:
            filled_filter = False

    # Click the Search button (accessibility-role based)
    try:
        if await page.get_by_role("button", name="Search").count() > 0:
            await page.get_by_role("button", name="Search").first.click()
        else:
            # Some grids label it "Filter" or use a button with name "Go"; try common alternatives
            if await page.get_by_role("button", name="Filter").count() > 0:
                await page.get_by_role("button", name="Filter").first.click()
            elif await page.get_by_role("button", name="Go").count() > 0:
                await page.get_by_role("button", name="Go").first.click()
    except Exception:
        # If search click fails, continue — we'll scan whatever rows are present
        pass

    await page.wait_for_load_state("networkidle")

    # 3) Find the product row containing Desiree, Black, XS (and maybe "fitness")
    target_row = None
    rows = page.get_by_role("row")
    row_count = 0
    try:
        row_count = await rows.count()
    except Exception:
        row_count = 0

    keywords_strict = ["desiree", "black", "xs", "fitness"]
    keywords_relaxed = ["desiree", "black", "xs"]

    # Try strict match first
    for i in range(row_count):
        r = rows.nth(i)
        try:
            txt = (await r.inner_text()).lower()
        except Exception:
            txt = ""
        if all(k in txt for k in keywords_strict):
            target_row = r
            break

    # Relaxed match
    if target_row is None:
        for i in range(row_count):
            r = rows.nth(i)
            try:
                txt = (await r.inner_text()).lower()
            except Exception:
                txt = ""
            if all(k in txt for k in keywords_relaxed):
                target_row = r
                break

    # Final fallback: match by 'fitness' and 'desiree'
    if target_row is None:
        for i in range(row_count):
            r = rows.nth(i)
            try:
                txt = (await r.inner_text()).lower()
            except Exception:
                txt = ""
            if "fitness" in txt and "desiree" in txt:
                target_row = r
                break

    if target_row is None:
        raise Exception("Could not locate the product row for Desiree's black fitness t-shirt size XS.")

    # 4) Click the product link inside that row to open the edit page
    try:
        if await target_row.get_by_role("link").count() > 0:
            await target_row.get_by_role("link").first.click()
        else:
            # If no explicit link role, try clicking the first button in the row named "Edit"
            if await target_row.get_by_role("button", name="Edit").count() > 0:
                await target_row.get_by_role("button", name="Edit").first.click()
            else:
                # As last resort, click the first link-like element by role
                await target_row.get_by_role("link").first.click()
    except Exception as e:
        raise Exception(f"Failed to open product edit from the located row: {e}")

    # Wait for navigation to the edit page
    await page.wait_for_load_state("networkidle")

    # 5) Find the price input and adjust the value
    price_input = None
    try:
        # Most form inputs have role textbox; prefer one named "Price"
        if await page.get_by_role("textbox", name="Price").count() > 0:
            price_input = page.get_by_role("textbox", name="Price").first
    except Exception:
        price_input = None

    # Fallback: try label-based access
    if price_input is None:
        try:
            if await page.get_by_label("Price").count() > 0:
                price_input = page.get_by_label("Price").first
        except Exception:
            price_input = None

    # Another fallback: any textbox whose label or surrounding text contains 'price'
    if price_input is None:
        try:
            textboxes = page.get_by_role("textbox")
            tb_count = await textboxes.count()
            for i in range(tb_count):
                tb = textboxes.nth(i)
                try:
                    ctx = (await tb.inner_text()).lower()
                except Exception:
                    ctx = ""
                # inner_text() on the textbox itself may be empty; try its accessible name
                name = await tb.get_attribute("name") if hasattr(tb, "get_attribute") else None
                if (name and "price" in (name or "").lower()) or "price" in ctx:
                    price_input = tb
                    break
        except Exception:
            price_input = None

    if price_input is None:
        raise Exception("Could not find the price input on the product edit page.")

    # Read current price value
    raw_val = await price_input.input_value()
    cleaned = raw_val.replace("$", "").replace(",", "").strip()
    try:
        current_price = float(cleaned)
    except Exception:
        # Extract first numeric occurrence
        import re
        m = re.search(r"[0-9]+(?:\.[0-9]+)?", cleaned)
        if not m:
            raise Exception(f"Unable to parse current price from '{raw_val}'")
        current_price = float(m.group(0))

    new_price = round(current_price * 1.37, 2)

    # Fill new price
    await price_input.fill(str(new_price))

    # Save the product using accessibility-role based button
    try:
        if await page.get_by_role("button", name="Save").count() > 0:
            await page.get_by_role("button", name="Save").first.click()
        elif await page.get_by_role("button", name="Save and Continue Edit").count() > 0:
            await page.get_by_role("button", name="Save and Continue Edit").first.click()
        else:
            # try any button containing the word Save
            buttons = page.get_by_role("button")
            btn_count = await buttons.count()
            clicked = False
            for i in range(btn_count):
                b = buttons.nth(i)
                try:
                    txt = (await b.inner_text()).lower()
                except Exception:
                    txt = ""
                if "save" in txt:
                    await b.click()
                    clicked = True
                    break
            if not clicked:
                raise Exception("Could not find a Save button to submit the product form.")
    except Exception as e:
        raise Exception(f"Failed to save the product: {e}")

    # Wait for save to complete
    await page.wait_for_load_state("networkidle")

